/**
 * One-time sign-in to chatgpt.com using the persistent Playwright profile.
 *
 * Unlike the DeepSeek extractor, we don't capture a token — the ChatGPT
 * provider uses Playwright as transport, so the only artifact we need is
 * the cookie jar inside the persistent profile. This script:
 *
 *   1. Opens Chrome (headed by default) with profile `.chatgpt-research/chrome-profile`.
 *   2. Navigates to chatgpt.com and waits up to 5 minutes for sign-in.
 *   3. Verifies via /api/auth/session that we have an authenticated session.
 *   4. Closes the window and reports.
 *
 * Outputs one JSON line to stdout:
 *   { "success": true,  "verifiedAs": "user@example.com" }
 *   { "success": false, "error": "...", "code": "..." }
 *
 * Usage:
 *   npm run chatgpt:setup           # headed (default — needed first time)
 *   npm run chatgpt:setup -- --verify   # just verify the saved profile
 *
 * Notes:
 *   - We never call process.exit() directly. Setting process.exitCode and
 *     returning from main() lets Node drain libuv handles cleanly on
 *     Windows (avoids the UV_HANDLE_CLOSING crash).
 */

import { mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT     = process.env.AI_PROVIDERS_CONSUMER_ROOT ?? process.cwd();
const RESEARCH = join(ROOT, ".chatgpt-research");
const PROFILE  = join(RESEARCH, "chrome-profile");

const flags    = new Set(process.argv.slice(2));
const VERIFY   = flags.has("--verify");
const HEADLESS = flags.has("--headless");
const VERBOSE  = flags.has("--verbose");

const TARGET   = "https://chatgpt.com";

function log(...args) {
  if (VERBOSE) console.error("[chatgpt-setup]", ...args);
}

function out(payload) {
  console.log(JSON.stringify(payload));
}

async function main() {
  mkdirSync(RESEARCH, { recursive: true });
  mkdirSync(PROFILE,  { recursive: true });

  const { chromium } = await import("playwright");

  // Verify mode is still headless: just check whether the saved cookies
  // give us an authenticated session.
  const headed = VERIFY ? false : !HEADLESS;

  log(`Launching Chrome (${headed ? "headed" : "headless"}) with profile: ${PROFILE}`);

  const ctx = await chromium.launchPersistentContext(PROFILE, {
    channel:    "chrome",
    headless:   !headed,
    viewport:   { width: 1366, height: 768 },
    locale:     "en-US",
    timezoneId: "Asia/Riyadh",
    args: [
      "--disable-blink-features=AutomationControlled",
      "--exclude-switches=enable-automation",
      "--no-first-run",
      "--no-default-browser-check",
    ],
    ignoreDefaultArgs: ["--enable-automation"],
  }).catch(err => {
    out({ success: false, error: `Chrome launch failed: ${err.message}`, code: "LAUNCH_FAILED" });
    return null;
  });

  if (!ctx) return 1;

  await ctx.addInitScript(() => {
    Object.defineProperty(navigator, "webdriver", { get: () => undefined });
    Object.defineProperty(navigator, "languages",  { get: () => ["en-US", "en", "ar"] });
  });

  const page = ctx.pages()[0] ?? await ctx.newPage();

  try {
    await page.goto(TARGET, { waitUntil: "domcontentloaded", timeout: 45_000 });
  } catch (err) {
    await ctx.close();
    out({ success: false, error: `Navigation failed: ${err.message}`, code: "NAVIGATION_FAILED" });
    return 1;
  }

  // Allow the page to fully settle (Cloudflare clearance, service worker).
  await page.waitForLoadState("networkidle", { timeout: 20_000 }).catch(() => { /* best-effort */ });

  async function checkSession() {
    return await page.evaluate(async () => {
      try {
        const r = await fetch("/api/auth/session", {
          credentials: "include",
          headers: { accept: "application/json" },
        });
        if (!r.ok) return { ok: false, status: r.status };
        const body = await r.json();
        if (!body || !body.accessToken) return { ok: false, status: r.status, signedOut: true };
        const u = body.user ?? {};
        return { ok: true, identity: u.email ?? u.name ?? u.id ?? "verified" };
      } catch (e) {
        return { ok: false, error: String(e?.message ?? e) };
      }
    }).catch(() => ({ ok: false, error: "evaluate failed" }));
  }

  let session = await checkSession();

  if (VERIFY) {
    await ctx.close();
    if (session?.ok) {
      out({ success: true, verifiedAs: session.identity, mode: "verify-only" });
      return 0;
    }
    out({
      success: false,
      error: "Profile exists but not signed in. Run: npm run chatgpt:setup",
      code: session?.signedOut ? "SIGNED_OUT" : "VERIFY_FAILED",
    });
    return 1;
  }

  // Wait up to 5 minutes for the user to sign in.
  if (!session?.ok) {
    log("Waiting up to 5 minutes for sign-in (close the window or sign in)...");
    const deadline = Date.now() + 5 * 60_000;
    while (Date.now() < deadline) {
      await page.waitForTimeout(3000);
      session = await checkSession();
      if (session?.ok) break;
    }
  }

  await ctx.close();

  if (session?.ok) {
    out({ success: true, verifiedAs: session.identity });
    return 0;
  }

  out({
    success: false,
    error: "Timed out waiting for sign-in. Re-run: npm run chatgpt:setup",
    code: "NOT_LOGGED_IN",
  });
  return 2;
}

process.exitCode = await main();
